	ImageEdits         []ImageEdit     `json:"image_edits,omitempty"`
	SmartArtEdits      []SmartArtEdit  `json:"smartart_edits,omitempty"`
	Notes              string          `json:"notes,omitempty"`
	SpeakerNotes       string          `json:"speaker_notes,omitempty"`
